  "claims": [
    {
      "claim": "La protection de l'assurance-accidents prend fin après la fin du droit à au moins la moitié du salaire.",
      "verdict": "supported"
    },
    {
      "claim": "Après la dernière perception d'indemnités de chômage, la couverture cesse si la personne n'a pas de nouveau contrat d'assurance ou d'activité professionnelle soumise à l'assurance-accidents obligatoire.",
      "verdict": "supported"
    },
    {
      "claim": "Il n'existe pas de prolongation automatique de la protection une fois que le droit aux prestations liées au salaire ou aux indemnités de chômage s'éteint.",
      "verdict": "supported"
    },
    {
      "claim": "Pour maintenir une couverture, il faut soit retrouver un emploi soumis à l'assurance-accidents obligatoire, soit souscrire une assurance-accidents facultative.",
      "verdict": "supported"
    },
    {
      "claim": "En cas d'accident survenu pendant une période d'assurance, les conséquences de l'accident sont prises en charge même si la couverture initiale a pris fin, jusqu'à la guérison complète ou l'octroi d'une rente.",
      "verdict": "supported"
    }
  ],
